 Let's imagine it's Wednesday. You can use symbol as an alternative for day of the week for this test case.
class Solution {
    public int countUSStates(String states, String preSuffix) {
        return (int) (states.split(" ")[0].length() == preSuffix.length() ? 1 : 0);
    }
    public static void main(String args[]) {
        System.out.println(countUSStates("Maine","e"));
    }
}


